-- Function: public.fn_get_dashboard_branch_metrics
-- Backup generated on 2026-10-25 20:33:14

CREATE OR REPLACE FUNCTION public.fn_get_dashboard_branch_metrics(p_tenant_id uuid, p_organization_id uuid)  RETURNS TABLE(branch_id uuid, branch_name character varying, location character varying, status text, classrooms integer, children integer, experiences integer)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT          b.id AS branch_id,          b.name::VARCHAR AS branch_name,          b.location::VARCHAR AS location,          CASE WHEN b.is_active THEN 'Active'::TEXT ELSE 'Inactive'::TEXT END AS status,         (SELECT COUNT(*)::INT FROM classrooms c WHERE c.branch_id = b.id AND c.tenant_id = p_tenant_id) AS classrooms,         (SELECT COUNT(*)::INT FROM children ch JOIN classrooms c ON ch.classroom_id = c.id WHERE c.branch_id = b.id AND ch.tenant_id = p_tenant_id) AS children,         (SELECT COUNT(*)::INT FROM experience_schedules es JOIN classrooms c ON es.classroom_id = c.id WHERE c.branch_id = b.id AND es.tenant_id = p_tenant_id) AS experiences     FROM branches b     WHERE b.organization_id = p_organization_id AND b.tenant_id = p_tenant_id     ORDER BY b.name; END; $function$ ;
